css:
#pill { position:absolute; left:60px; bottom:176px; height:96px; display:flex; align-items:center; gap:22px; background:rgba(12,12,12,.9); border-radius:48px; padding:0 18px 0 14px; box-shadow:0 14px 40px rgba(0,0,0,.45); }
#logo { width:68px; height:68px; border-radius:50%; background:var(--red); display:flex; align-items:center; justify-content:center; font-weight:700; font-size:36px; }
#name { font-weight:700; font-size:34px; }
#tagline { font-weight:400; font-size:22px; opacity:.8; margin-top:2px; }
#btn { position:relative; margin-left:14px; background:var(--red); color:#fff; font-weight:700; font-size:28px; letter-spacing:.06em; border-radius:30px; padding:14px 30px 12px; }
#done { position:absolute; inset:0; border-radius:30px; background:#3a3a3a; color:#ddd; display:flex; align-items:center; justify-content:center; opacity:0; }
#bell { font-size:40px; opacity:0; }
#cursor { position:absolute; width:46px; height:46px; border-radius:50%; background:rgba(255,255,255,.95); box-shadow:0 0 0 6px rgba(255,255,255,.25); opacity:0; }

js:
document.getElementById('name').textContent = V.channel;
document.getElementById('logo').textContent = V.channel.slice(0, 1).toUpperCase();
const D = V.duration;
const btn = document.getElementById('btn').getBoundingClientRect();
const cx = btn.left + btn.width / 2 - 23, cy = btn.top + btn.height / 2 - 23;
tl.fromTo('#pill', { x: -700, opacity: 0 }, { x: 0, opacity: 1, duration: 0.55, ease: 'power3.out' }, 0);
tl.fromTo('#cursor', { x: cx + 260, y: cy + 160, opacity: 0 }, { x: cx, y: cy, opacity: 1, duration: 0.7, ease: 'power2.inOut' }, 0.9);
tl.to('#cursor', { scale: 0.75, duration: 0.12 }, 1.65);
tl.to('#btn', { scale: 0.92, duration: 0.12 }, 1.65);
tl.to('#cursor', { scale: 1, duration: 0.15 }, 1.8);
tl.to('#btn', { scale: 1, duration: 0.18 }, 1.8);
tl.to('#done', { opacity: 1, duration: 0.2 }, 1.8);
tl.to('#bell', { opacity: 1, duration: 0.25 }, 2.3);
tl.fromTo('#bell', { rotation: -20 }, { rotation: 20, duration: 0.12, repeat: 5, yoyo: true }, 2.35);
tl.to('#cursor', { opacity: 0, duration: 0.3 }, 2.6);
tl.to('#pill', { x: -700, opacity: 0, duration: 0.45, ease: 'power2.in' }, D - 0.5);
